#include <iostream>

int main() {
    int x = 5;
    int* p = &x;                      // p zeigt auf x

    std::cout << "Wert: " << *p << std::endl;

    bool gleich = (p == &x);
    std::cout << "Gleiche Adresse: " << (gleich ? "ja" : "nein") << std::endl;

    *p = 12;                          // aendert x selbst
    std::cout << "x ist " << x << std::endl;

    return 0;
}

#include <iostream>
#include <string>

void haengt_an(std::string& text) {          // arbeitet am Original
    text += "!";
}

void zeigt(const std::string& text) {        // liest nur, keine Kopie
    std::cout << "Gelesen: " << text << std::endl;
}

void nur_kopie(std::string text) {           // eigene Kopie
    text += "?";
    std::cout << "In der Kopie: " << text << std::endl;
}

int main() {
    std::string text = "Hallo";

    haengt_an(text);
    zeigt(text);
    nur_kopie(text);
    std::cout << "Original: " << text << std::endl;

    return 0;
}

#include <iostream>

int main() {
    int* zahl = new int(42);
    std::cout << *zahl << std::endl;
    delete zahl;                 // einzelnes Objekt
    zahl = nullptr;

    int* feld = new int[5];
    for (int i = 0; i < 5; ++i) {
        feld[i] = i * i;
    }

    int summe = 0;
    for (int i = 0; i < 5; ++i) {
        summe += feld[i];
    }
    std::cout << summe << std::endl;

    delete[] feld;               // Feld: eckige Klammern nicht vergessen
    feld = nullptr;

    return 0;
}

#include <iostream>
#include <memory>

int main() {
    auto zahl = std::make_unique<int>(7);
    std::cout << *zahl << std::endl;

    auto feld = std::make_unique<int[]>(4);
    for (int i = 0; i < 4; ++i) {
        feld[i] = (i + 1) * 10;
    }
    std::cout << feld[0] + feld[3] << std::endl;

    return 0;                    // kein delete noetig
}

