#include <iostream>
#include <memory>
#include <string>

class Waechter {
public:
    explicit Waechter(const std::string& name) : name_(name) {
        std::cout << "geholt: " << name_ << std::endl;
    }
    ~Waechter() {
        std::cout << "freigegeben: " << name_ << std::endl;
    }

private:
    std::string name_;
};

int main() {
    {
        auto erstes = std::make_unique<Waechter>("erstes");
        auto zweites = std::make_unique<Waechter>("zweites");
    }                            // hier laufen beide Destruktoren
    std::cout << "Block zu Ende" << std::endl;
    return 0;
}

#include <iostream>

// Der Aufrufer wird Eigentuemer und muss delete[] aufrufen.
int* feld_erzeugen(int anzahl) {
    int* feld = new int[anzahl];
    for (int i = 0; i < anzahl; ++i) {
        feld[i] = i + 1;
    }
    return feld;
}

int main() {
    const int anzahl = 4;
    int* feld = feld_erzeugen(anzahl);

    int summe = 0;
    for (int i = 0; i < anzahl; ++i) {
        summe += feld[i];
    }
    std::cout << summe << std::endl;

    delete[] feld;
    feld = nullptr;

    return 0;
}
